    "substring": { minArgs: 2, maxArgs: 3, signature: "substring(s, start, [length])", forms: [["s", "start", "[length]"]], description: "returns length characters of s starting at start. If length is not supplied, it returns the rest of the string", details: "", params: {"start": "index of the first character", "length": "number of characters (default: the rest of the text)"}, aliases: ["substr"] },
